-- Synthetic, isolated test database only. Execute using isql -b.
CREATE TABLE OTEL_A (ID INTEGER PRIMARY KEY, VAL INTEGER);
CREATE TABLE OTEL_B (ID INTEGER, VAL INTEGER);
CREATE VIEW OTEL_V AS SELECT ID, VAL FROM OTEL_A;
SET TERM ^;
CREATE FUNCTION OTEL_DOUBLE (N INTEGER) RETURNS INTEGER AS BEGIN RETURN N * 2; END^
CREATE PROCEDURE OTEL_NESTED_A (N INTEGER) AS BEGIN UPDATE OTEL_A SET VAL = OTEL_DOUBLE(:N) WHERE ID = 1; END^
CREATE PROCEDURE OTEL_NESTED_B (N INTEGER) AS BEGIN INSERT INTO OTEL_B VALUES (:N, :N); END^
CREATE PROCEDURE OTEL_OUTER (N INTEGER) AS
BEGIN
 EXECUTE PROCEDURE OTEL_NESTED_A(:N);
 IF (N < 0) THEN EXECUTE PROCEDURE OTEL_NESTED_B(:N);
END^
CREATE TRIGGER OTEL_A_CHANGED FOR OTEL_A AFTER UPDATE AS BEGIN INSERT INTO OTEL_B VALUES (NEW.ID, NEW.VAL); END^
CREATE PROCEDURE OTEL_REPORT RETURNS (N INTEGER) AS BEGIN N = 1; SUSPEND; N = 2; SUSPEND; END^
CREATE PROCEDURE OTEL_RECURSE (N INTEGER) AS BEGIN IF (N > 0) THEN EXECUTE PROCEDURE OTEL_RECURSE(:N - 1); END^
CREATE PROCEDURE OTEL_DYNAMIC AS DECLARE N INTEGER; BEGIN EXECUTE STATEMENT 'select count(*) from OTEL_B' INTO :N; END^
CREATE PACKAGE OTEL_PACKAGE AS BEGIN PROCEDURE MEMBER(N INTEGER); END^
CREATE PACKAGE BODY OTEL_PACKAGE AS BEGIN PROCEDURE MEMBER(N INTEGER) AS BEGIN EXECUTE PROCEDURE OTEL_NESTED_A(:N); END END^
CREATE PROCEDURE OTEL_PACKAGED_CALL AS BEGIN EXECUTE PROCEDURE OTEL_PACKAGE.MEMBER(1); END^
SET TERM ;^
INSERT INTO OTEL_A VALUES (1, 0);
COMMIT;
